  '6d8cb6c5-8588-4ddc-a5d8-91cf4ef2701d'::uuid, 'instagram_reels', 'reels', 'en', 'en-US',
  'Luxury practical sequence Founder Taste Audit Brief 009', 'For Luxury content, the Reel opens on a quiet checkout moment, uses a mini checklist, and resolves simple but overlooked with a micro tutorial. The creative lane is a practical sequence built around a boundary card.',
  'SAFE'::public.safety_status, 'PASS'::public.review_decision, 'high', 'published'::public.idea_status,
  '{"validation": {"safety": true, "schema": true, "platform_fit": true, "category_persona_fit": true, "category_layer_policy": true}, "safety_notes": [], "import_source": "admin_batch_import", "category_layer_policy": {"scope_type": "category", "policy_slug": "luxury_signal_policy", "premium_layers": ["ritual_series_layer"], "creator_visible": false, "required_layers": ["brand_lift_layer", "creator_style_adapter", "scene_energy_curve_layer", "risk_reputation_layer", "platform_conversion_layer", "luxury_signal_layer", "status_shift_layer", "sponsor_softness_layer"]}}'::jsonb,
  (select id from public.categories where slug = 'luxury'),
  coalesce((select id from public.creator_personas where slug = 'style_strategist' limit 1), (select id from public.creator_personas where slug = 'expert_guide' limit 1), (select id from public.creator_personas limit 1)),
  'admin_direct'::public.generation_source_mode,
  '["The part that looks effortless is actually one small mini checklist.", "Before you copy the final result, look at this practical sequence filter.", "This is the Luxury decision filter I would save first.", "The premium version is not louder; it is more selective about simple but overlooked.", "Which option would you remove from this setup?"]'::jsonb, '["visual hook", "premise", "proof detail", "decision boundary", "payoff", "comment prompt", "save CTA"]'::jsonb, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb
)
on conflict (id) do update set
